# Unified hypothesis across all four demos:
#   bg = most common color.
#   marker color M = rarest non-bg color (appears once or twice, as single isolated cells AND once inside the big template).
#   template = large connected comp of non-bg containing an M-cell (anchor). Its other cells get replaced by stamp color S (the remaining non-bg color).
#   For each marker (M-cell elsewhere): stamp = translate template so its anchor lands ON the marker; stamp cells OVERWRITE everything (bg or marker) -> but do they overwrite the marker itself? In D1 output marker at (4,15) STAYS 2 while stamp 7s appear around it. Actually check whether marker cell itself changes.
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    nb=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=bg]
    mc=Counter(v for _,_,v in nb)
    anc=min(mc,key=lambda c:mc[c])   # anchor color = rarest
    S=max([c for c in mc if c!=anc],key=lambda c:mc[c]) if len(set(mc)-{anc})==1 else None
    used=set(); tmpl=None; anch=None
    for (y,x,v) in nb:
        if v==anc and (y,x) not in used:
            st=[(y,x)]; used.add((y,x)); comp=[]
            while st:
                yy,xx=st.pop(); comp.append((yy,xx,g[yy][xx]))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        if dy==dx==0: continue
                        q=(yy+dy,xx+dx)
                        if 0<=q[0]<H and 0<=q[1]<W and (q not in used and g[q[0]][q[1]]!=bg):
                            used.add(q); st.append(q)
            tmpl=comp; break
    anch=[(y,x) for (y,x,v) in tmpl if v==anc][0]
    sh={(y-anch[0],x-anch[1]):v for (y,x,v) in tmpl}
    marks=[(y,x) for (y,x,v) in nb if v==anc and (y,x)!=(anch[0],anch[1])]
    out=[row[:] for row in g]
    for mi,mj in marks:
        t=(mi-anch[0],mj-anch[1])
        for (dy,dx),cv in sh.items():
            ny,nx=mi+t[0]+dy,mj+t[1]+dx
            if 0<=ny<H and 0<=nx<W: out[ny][nx]=S
    return out
