def comps_g_colored(I,bg):
    H,W=len(I),len(I[0]);seen=set();out=[]
    for y in range(H):
        for x in range(W):
            if (y,x) not in seen and I[y][x]!=bg:
                st=[(y,x)];seen.add((y,x));c=[]
                while st:
                    p=st.pop();c.append((p,I[p[0]][p[1]]))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=p[0]+dy,p[1]+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and I[ny][nx]!=bg:
                            seen.add((ny,nx));st.append((ny,nx))
                out.append(c)
